//! Embedded data generated by scripts/translation_data.py from Mojang's server
//! data reports. Parsed once on first use; a malformed file is a build defect,
//! caught by this module's tests rather than surfacing at runtime.
use serde::Deserialize;
use std::collections::HashMap;

#[derive(Deserialize)]
pub(super) struct Version {
    pub protocol: i32,
    /// Layout-selecting registries, names in network-ID order.
    pub registries: HashMap<String, Vec<String>>,
    /// `"<state>/<direction>"` to packet names in packet-ID order.
    pub packets: HashMap<String, Vec<String>>,
}

impl Version {
    pub fn registry(&self, name: &str) -> &[String] {
        self.registries
            .get(name)
            .unwrap_or_else(|| panic!("translation data lacks {name}"))
    }

    pub fn packets(&self, key: &str) -> &[String] {
        self.packets
            .get(key)
            .unwrap_or_else(|| panic!("translation data lacks {key} packets"))
    }
}

#[derive(Deserialize)]
pub(super) struct Step {
    pub from: i32,
    pub to: i32,
    pub registries: HashMap<String, RegistryDiff>,
    /// Packet ID changes by `"<state>/<direction>"`; a step must handle each.
    pub packets: HashMap<String, serde_json::Value>,
}

/// The newer registry as the older one plus insertions and minus removals,
/// otherwise in the same order. Each side names a stand-in for entries the
/// other lacks: `[new_id, name, old_stand_in, old_stand_in_name]` for inserted
/// entries and `[old_id, name, new_stand_in, new_stand_in_name]` for removed.
#[derive(Deserialize)]
pub(super) struct RegistryDiff {
    pub old_size: usize,
    pub new_size: usize,
    pub inserted: Vec<(usize, String, usize, String)>,
    pub removed: Vec<(usize, String, usize, String)>,
}

impl RegistryDiff {
    /// Old network ID to new network ID.
    pub fn upgrade(&self) -> Vec<i32> {
        let inserted: Vec<_> = self.inserted.iter().map(|entry| entry.0).collect();
        let mut table = Vec::with_capacity(self.old_size);
        let mut next = 0;
        for old in 0..self.old_size {
            if let Some(entry) = self.removed.iter().find(|entry| entry.0 == old) {
                table.push(entry.2 as i32);
                continue;
            }
            while inserted.contains(&next) {
                next += 1;
            }
            table.push(next as i32);
            next += 1;
        }
        table
    }

    /// New network ID to old network ID.
    pub fn downgrade(&self) -> Vec<i32> {
        let upgrade = self.upgrade();
        let mut table = vec![-1; self.new_size];
        for (old, &new) in upgrade.iter().enumerate() {
            if !self.removed.iter().any(|entry| entry.0 == old) {
                table[new as usize] = old as i32;
            }
        }
        for (new, _, fallback, _) in &self.inserted {
            table[*new] = *fallback as i32;
        }
        table
    }
}

/// A registry mapping in one direction: source network ID to target ID.
pub(super) type IdMap = Vec<i32>;

pub(super) fn version(json: &str) -> Version {
    serde_json::from_str(json).expect("embedded translation version data")
}

pub(super) fn step(json: &str) -> Step {
    serde_json::from_str(json).expect("embedded translation step data")
}
